/**
 * Union of the ids the client already resolved (optimistic UI) and the ones
 * parsed out of the body server-side. Only current members of the workspace
 * survive either source; anyone else is dropped silently, never notified.
 */
async function resolveMentionedUsers(
  orgId: OrgId,
  body: string,
  clientProvided: readonly UserId[],
): Promise<readonly UserId[]> {
  const members = await memberRepo.listMembers({
    orgId,
    limit: MENTION_LOOKUP_LIMIT,
    cursor: null,
  });

  const resolved = resolveMentions(body, members.items);

  const provided = await Promise.all(
    clientProvided.map(async (userId) =>
      (await memberRepo.findMember(orgId, userId)) === null ? null : userId,
